def bin_center_percentiles(nbins: int, mode: str = "paper_eq4") -> np.ndarray:
    """Percentile levels for the bin centers.

    mode "paper_eq4" (primary): (k-1)*100/(nbins-1), k = 1..nbins  -- paper Eq. (4),
        so the first/last centers are the observed min/max.
    mode "midpoint": (k-0.5)*100/nbins   (sensitivity variant)
    mode "k_over_n": k*100/nbins         (sensitivity variant)
    """
    if nbins < 2:
        raise ValueError("nbins must be >= 2 (Eq. 4 divides by nbins-1)")
    k = np.arange(1, nbins + 1, dtype=float)
    if mode == "paper_eq4":
        return (k - 1) * 100.0 / (nbins - 1)
    if mode == "midpoint":
        return (k - 0.5) * 100.0 / nbins
    if mode == "k_over_n":
        return k * 100.0 / nbins
    raise ValueError(f"unknown percentile mode {mode!r}")

